document.addEventListener("DOMContentLoaded",()=>{const faqsWrap=document.querySelector('.faqs-wrap');if(!faqsWrap.classList.contains('anim')){faqsWrap.classList.add('anim')}
faqsWrap.addEventListener('click',(e)=>{const faq=e.target.closest('.faq');if(!faq)return;const answer=faq.querySelector('.answer');const isOpened=faq.classList.contains('opened');faqsWrap.querySelectorAll('.faq.opened').forEach(el=>{if(el!==faq){el.classList.remove('opened');slideUp(el.querySelector('.answer'),300)}});if(isOpened){faq.classList.remove('opened');slideUp(answer,300)}else{faq.classList.add('opened');slideDown(answer,300)}});function slideUp(element,duration=300){element.style.height=element.offsetHeight+'px';element.style.transition=`height ${duration}ms ease`;element.offsetHeight;element.style.height='0';element.style.overflow='hidden';setTimeout(()=>{element.style.display='none';element.style.height='';element.style.overflow='';element.style.transition=''},duration)}
function slideDown(element,duration=300){element.style.removeProperty('display');let display=window.getComputedStyle(element).display;if(display==='none')display='block';element.style.display=display;const height=element.offsetHeight;element.style.height='0';element.style.overflow='hidden';element.offsetHeight;element.style.transition=`height ${duration}ms ease`;element.style.height=height+'px';setTimeout(()=>{element.style.height='';element.style.overflow='';element.style.transition=''},duration)}})